{
    using System.Text;
    using Fanex.BetList.Core.Templates;
    using NUnit.Framework;

    public class WrapperOdds_Template : Odds_Template
    {
        public void SetAssigned(bool isAssigned)
        {
            this.IsAssigned = isAssigned;
        }

